-- Engine running hours at delivery (pickup) and collection (return), plus on-screen signatures.
--
-- Signatures are small SVG drawings generated by the staff app. submit-inspection re-reads each
-- file and only accepts a bare <svg> of <path d="..."> strokes, so nothing executable is stored.

alter table public.vehicles add column engine_hours numeric(8, 1) check (engine_hours >= 0);
alter table public.inspections add column engine_hours numeric(8, 1) check (engine_hours >= 0);
comment on column public.inspections.engine_hours is 'Engine hour meter reading; null when the vehicle has no hour meter.';

update storage.buckets
   set allowed_mime_types = array['image/jpeg', 'image/png', 'image/heic', 'image/svg+xml']
 where id = 'inspections';
